import React from "react";
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import Upload from "./components/Upload";
import Result from "./components/Result";
import Footer from "./components/Footer";
import "./App.css";

function App() {
  return (
    <div>
      <Navbar />
      <Hero />
      <Upload />
      <Result />
      <Footer />
    </div>
  );
}

export default App;
